/* * <stat.h> for OS-9. * * zoo's osk.c writes #include <stat.h>, which is where its author's system * kept it. Everything else here asks for <sys/stat.h>. One line rather than * an edit to the archive's source. *//* <UNIX/stat.h> DIRECTLY, not <sys/stat.h>, and that matters.  Going through   <sys/stat.h> means whichever sys/stat.h the include path finds first --   and a tree carrying its own, like SRC/ls, has one that says   #include <stat.h> to reach the system header.  The two then call each   other: stat.h -> sys/stat.h -> stat.h, and cccp2 recurses until it dies   with **** Stack Overflow ****, which reads like a broken source file and   is not one.  This is the same trap DEFS/blarsdefs/errno.h documents.   SRC/COMPAT/sys/stat.h resolves to exactly this header, so nothing that   worked before sees a different one.  -- osk-freeware, 2026-08-23 */#include <UNIX/stat.h>